// the existing paginated project-session endpoint. The caller owns cancellation.
export async function findDeepLinkedSession(
  projects: Project[], sessionId: string,
  getPage: (projectName: string, offset: number) => Promise<{ sessions?: ProjectSession[]; hasMore?: boolean }>,
  cancelled: () => boolean,
): Promise<{ project: Project; session: ProjectSession } | null> {
  const matches: Array<{ project: Project; session: ProjectSession }> = [];
  for (const project of projects) {
    if (project.sessionMeta?.hasMore === false) continue;
    let offset = 0;
    const seenPages = new Set<string>();
    for (;;) {
      if (cancelled()) return null;
      if (seenPages.size >= 200) throw new Error('Session lookup exceeds page limit');
      const page = await getPage(project.name, offset);
      if (cancelled()) return null;
      if (!Array.isArray(page.sessions) || typeof page.hasMore !== 'boolean') throw new Error('Invalid session page');
      const signature = JSON.stringify(page.sessions.map(session => session.id));
      if (seenPages.has(signature)) throw new Error('Repeated session page');
      seenPages.add(signature);
      for (const session of page.sessions) {
        if (session?.id === sessionId && !matches.some(match => match.project.name === project.name)) matches.push({ project, session });
      }
      if (!page.hasMore) break;
      if (!page.sessions.length) throw new Error('Empty session page with more results');
      offset += page.sessions.length;
    }
  }
  if (matches.length > 1) throw new Error('Session belongs to multiple projects');
  return matches[0] ?? null;
}

